# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def isSymmetric(self, root: Optional[TreeNode]) -> bool:
        def mirror(l, r):
            if not l and not r:   # 双空 → 对称
                return True
            if not l or not r or l.val != r.val:
                return False
            # 镜像递归：外侧对外侧，内侧对内侧
            return mirror(l.left, r.right) and mirror(l.right, r.left)
        return mirror(root.left, root.right)

from collections import deque

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def levelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []
        res, q = [], deque([root])
        while q:
            n, level = len(q), []   # n = 本层节点数
            for _ in range(n):
                node = q.popleft()
                level.append(node.val)
                if node.left:  q.append(node.left)
                if node.right: q.append(node.right)
            res.append(level)
        return res

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        def check(node, lo, hi):
            if not node:
                return True
            if not (lo < node.val < hi):  # 必须落在开区间内
                return False
            return (check(node.left, lo, node.val) and   # 收紧上界
                    check(node.right, node.val, hi))     # 收紧下界
        return check(root, float("-inf"), float("inf"))

from collections import deque

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:
        if not root:
            return []
        res, q = [], deque([root])
        while q:
            n = len(q)
            for i in range(n):
                node = q.popleft()
                if i == n - 1:      # 本层最后一个 = 最右
                    res.append(node.val)
                if node.left:  q.append(node.left)
                if node.right: q.append(node.right)
        return res
